def add_two_numbers(l1, l2):
    def value(node):
        total, place = 0, 1
        while node:
            total += node.val * place
            place *= 10
            node = node.next
        return total

    s = value(l1) + value(l2)
    dummy = tail = ListNode()
    while True:
        s, d = divmod(s, 10)
        tail.next = tail = ListNode(d)
        if s == 0:
            return dummy.next
